import json

def build_adjacency(edges):
    adj = {}
    for a, b in edges:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)
    # sort neighbors for deterministic traversal
    return {k: sorted(v) for k, v in adj.items()}

def find_hamiltonian_path(adj, nodes, end_city):
    nodes_set = set(nodes)
    starts = [n for n in sorted(nodes) if n != end_city]

    def dfs(current, visited, path):
        if len(path) == len(nodes):
            return path if current == end_city else None
        for neigh in adj.get(current, []):
            if neigh in visited:
                continue
            res = dfs(neigh, visited | {neigh}, path + [neigh])
            if res is not None:
                return res
        return None

    for start in starts:
        res = dfs(start, {start}, [start])
        if res is not None and res[-1] == end_city and len(res) == len(nodes):
            return res
    return None

def compute_day_ranges(order, durations, total_days):
    # Compute ranges backward so that the last city ends on total_days
    ranges = {}
    current_end = total_days
    for city in reversed(order):
        dur = durations[city]
        start = current_end - dur + 1
        ranges[city] = (start, current_end)
        current_end = start  # flight day overlaps with previous city's last day
    return [({"place": city, "day_range": f"Day {ranges[city][0]}-{ranges[city][1]}"}) for city in order], ranges

def validate_constraints(order, adj, durations, total_days, friend_city, friend_window):
    # adjacency check
    for i in range(len(order) - 1):
        if order[i+1] not in adj.get(order[i], []):
            return False, "Non-direct flight detected between {} and {}".format(order[i], order[i+1])

    # total unique days logic: unique_days = sum(durations) - (flights)
    sum_durs = sum(durations[c] for c in order)
    flights = len(order) - 1
    if sum_durs - flights != total_days:
        return False, "Total days do not align with durations and flights"

    # Porto meeting window check
    itinerary_list, ranges = compute_day_ranges(order, durations, total_days)
    porto_start, porto_end = ranges[friend_city]
    win_start, win_end = friend_window
    # Require at least overlap with the window
    overlap = not (porto_end < win_start or porto_start > win_end)
    if not overlap:
        return False, "Porto stay does not overlap friend meeting window"

    # Ensure itinerary starts at Day 1
    first_city = order[0]
    if ranges[first_city][0] != 1:
        return False, "Itinerary does not start on Day 1"

    return True, itinerary_list

def main():
    # Input variables (constraints)
    total_days = 18
    friend_city = "Porto"
    friend_window = (16, 18)

    durations = {
        "Helsinki": 4,
        "Valencia": 5,
        "Dubrovnik": 4,
        "Porto": 3,
        "Prague": 3,
        "Reykjavik": 4
    }

    edges = [
        ("Helsinki", "Prague"),
        ("Prague", "Valencia"),
        ("Valencia", "Porto"),
        ("Helsinki", "Reykjavik"),
        ("Dubrovnik", "Helsinki"),
        ("Reykjavik", "Prague")
    ]

    nodes = list(durations.keys())
    adj = build_adjacency(edges)

    # Find a Hamiltonian path that ends at Porto
    order = find_hamiltonian_path(adj, nodes, friend_city)
    if order is None:
        raise RuntimeError("No valid path found with direct flights that visits all cities and ends in Porto.")

    valid, result_or_msg = validate_constraints(order, adj, durations, total_days, friend_city, friend_window)
    if not valid:
        raise RuntimeError(result_or_msg)

    itinerary_list = result_or_msg  # from validate_constraints
    print(json.dumps({"itinerary": itinerary_list}, ensure_ascii=False))

if __name__ == "__main__":
    main()
